    "landingProblemEyebrow": "ПРОБЛЕМА",
    "landingProblemTitleLine1": "Общее изучение финского языка",
    "landingProblemTitleLine2": "недостаточно для реальных результатов.",
    "landingProblemBody": "Общие языковые приложения абстрактно обучают финскому языку. Floently научит финскому языку, который вам действительно нужен для того, что изменит вашу жизнь: прохождения YKI, трудоустройства, получения гражданства.",
    "landingOutcomeWallTitle": "YKI — это стена, а не финишная черта",
    "landingOutcomeWallBody": "Многим учащимся нужно нечто большее, чем просто общие уроки языка. Финский язык им нужен для самого экзамена YKI, для работы, для повседневного общения — и для долгого пути к гражданству и постоянному месту жительства.",
    "landingOutcomeWorkplaceTitle": "Финский на рабочем месте – это другой навык",
    "landingOutcomeWorkplaceBody": "Международным сотрудникам нужен практичный финский для более безопасного общения во время смены, более плавного адаптации и владения языком, который способствует удержанию, а не трениям.",
    "landingOutcomeCitiesTitle": "Результаты интеграции принадлежат городам",
    "landingOutcomeCitiesBody": "Жителям нужна языковая поддержка, которая связывает обучение с возможностями трудоустройства, инклюзивностью и значимым участием в финском обществе, а не только сертификаты об окончании обучения.",
    "landingPlatformEyebrow": "ОДНА ПЛАТФОРМА, ТРИ ПУТИ",
    "landingPlatformTitleLine1": "YKI, рабочее место,",
    "landingPlatformTitleHighlight": "и жизнь в Финляндии.",
    "landingPlatformBody": "Три пути под одной платформой. Выберите тот, который соответствует вашей цели, или запустите все три для учреждения.",
    "landingPlatformYkiEyebrow": "YKI Подготовка",
    "landingPlatformYkiTitle": "Построен вокруг четырех экзаменационных навыков.",
    "landingPlatformYkiBody": "Устная речь, письмо, чтение, аудирование — практика под руководством инструктора с обратной связью, соответствующей критериям YKI для оценки работы, гражданства и постоянного места жительства.",
    "landingPlatformProfessionalEyebrow": "Профессиональный финский",
    "landingPlatformProfessionalTitle": "Для врачей, медсестер, практических медсестер.",
    "landingPlatformProfessionalBody": "Профессионально-специфичные сценарии, лексика и диалоги. Передача пациентов, клиническая документация, ежедневная командная работа — язык реальной работы, а не ситуаций из учебника.",
    "landingPlatformLifeEyebrow": "Жизнь в Финляндии",
    "landingPlatformLifeTitle": "Ежедневные службы, официальное общение.",
    "landingPlatformLifeBody": "Финский язык вам нужен для KELA, Migri, здравоохранения, школ, банков, а также для достижения долгосрочных целей получения гражданства и постоянного места жительства.",
    "landingInsideEyebrow": "ЧТО ВНУТРИ",
    "landingInsideTitleLine1": "Одна платформа, соединяющая",
    "landingInsideTitleLine2": "YKI, работа и поселение.",
    "landingInsideBody": "Каждый учащийся перемещается между подготовкой к экзамену, профессиональным финским и финским для повседневной жизни. Floently удерживает их на одном непрерывном пути.",
    "landingPathwayLearnersEyebrow": "Для учащихся",
    "landingPathwayLearnersTitle": "Пройдите YKI, подготовьтесь к работе, постройте долгосрочную финку.",
    "landingPathwayLearnersBody": "Практика чтения, аудирования, письма и разговорной речи, основанная на целях YKI и финском языке, который вам действительно нужен на работе и в повседневной жизни.",
    "landingPathwayLearnersCta": "Начать обучение",
