    "landingPathwayEmployersTitle": "Привлечение, удержание и защита международного персонала.",
    "landingPathwayEmployersBody": "Финский язык, адаптированный к рабочему месту, для более безопасного общения, более быстрого адаптации и более надежного долгосрочного удержания. Профессиональные пути в здравоохранении и за его пределами.",
    "landingPathwayEmployersCta": "Забронируйте демо-версию для работодателя",
