    "onboardingProfessionDoctorDetail": "Tương tác với bệnh nhân, giải thích, tài liệu và giao tiếp tại nơi làm việc trong môi trường chăm sóc sức khỏe.",
    "onboardingProfessionNurseDetail": "Chăm sóc bệnh nhân, bàn giao, báo cáo, làm việc nhóm và ngôn ngữ thực tế cho công việc điều dưỡng hàng ngày.",
