    "landingTrustProfessionSpecific": "Xirfad gaar ah",
    "landingTrustWorkplaceCommunication": "Isgaarsiinta goobta shaqada",
    "landingTrustSettlementSupport": "Taageerada dejinta",
    "landingTrustProgrammeScalable": "Barnaamij-la qiyaasi karo",
    "landingFinalEyebrow": "DIYAAR MARKAAD JOOGTID",
    "landingFinalTitleLine1": "Isku soo dhawoow barashada Finnishka",
    "landingFinalTitleLine2": "shaqo, dejin, iyo fursad.",
    "landingFinalBody": "Haddi aad isu diyaarinayso YKI, taageeridda shaqaalaha caalamiga ah, ama aad waddo barnaamij magaalo — Floently waxa loo dhisay natiijooyin dhab ah, ee ma aha buug-gacmeedka guud ee Finnishka.",
