    "learningDailyRoleplayDetail": "Fur jidka wada-hadalka guud ee la wadaago. Tani waxay ku xiran tahay qaybta maalinlaha ama YKI, ee kuma xirna ciyaar-doorarka xirfadda ee goobta shaqada.",
    "learningDailyRoleplayMeta": "Ciyaar doorar maalinle",
    "learningOpenRoleplay": "Fur ciyaar doorar",
    "learningHubEyebrow": "U diyaarsanaanta goobta shaqada",
    "learningHubTitle": "Af-Fiinish ee shaqada",
    "learningHubSubtitle": "Marka hore dooro laanta saxda ah. Af-Fiinishka maalin kasta waa la wadaagaa. Xirfadeyda waxay ilaalisaa dariiqa mihnadda ee lacagta lagu bixiyo iyo kaadhadhkeeda xasuusta, ciyaar-doorarka goobta shaqada, iyo aragtida waraysiga.",
    "learningEverydayCardDetail": "Fur laanta maalinlaha ah ee la wadaago marka hore. Intaa ka dib, dooro kaliya inta u dhaxaysa kaadhadhka xasuusta ee guud iyo ciyaar-doorarka maalinlaha ah.",
    "learningEverydayCardMeta": "Luqada la wadaago",
    "learningOpenEveryday": "Fur Af-Fiinish maalin kasta",
    "learningMyProfessionTitle": "Xirfadeyda",
    "learningMyProfessionDetail": "Fur laantaada xirfadda. Ka dooro Kalkaaliso, Dhaqtar, ama Kalkaaliso Dhaqan ah, ka dib isticmaal bogga xirfadda buuxda ee leh kaadhadhka xasuusta, ciyaar-doorarka goobta shaqada, iyo ku celcelinta waraysiga.",
    "learningOpenMyProfession": "Fur Xirfadeyda",
