    "speakingComingSoon": "Dhawaan imaanaya",
    "speakingInterviewComingSoonAccessibility": "Ku celcelinta waraysiga - dhawaan imanaya",
    "speakingInterviewBetaDetailFull": "Ku celcelinta wareysiga la qabsiga leh ee jawaab celinta naxwaha dhinac kasta - qayb ka mid ah matoorka Beta, oo hadda ku jira horumar. Waxaan furi doonaa foornadan marka ay diyaar noqoto.",
    "speakingInterviewBetaDetailShort": "Ku celcelinta wareysiga la qabsiga leh ee jawaab celinta naxwaha dhinac kasta - qayb ka mid ah matoorka Beta, oo hadda ku jira horumar.",
    "speakingRecordedTitle": "La duubay isagoo hadlaya",
    "speakingRecordedDetail": "Diiwaangeli cusboonaysiinta shaqada monologue oo dib u eeg bixintaada.",
    "speakingIncidentLabTitle": "Shaybaarka dhacdada",
    "speakingIncidentLabDetail": "Ku qor oo ku celceli ka warbixinta dhacdooyinka goobta shaqada af Finnish.",
    "speakingScenariosTitle": "Muuqaalo aad ku tababaran doonto",
    "speakingWhyRouteMattersTitle": "Waa maxay sababta wadadani muhiim u tahay",
    "speakingWhyRouteMattersText": "Tababarka halkan waa in uu dareemo in uu aad ugu dhow yahay nolosha shaqada ee Finland marka loo eego laylisyada hadalka guud. Ka dhig luqadda mid gaaban, cad, oo shaqo ku habboon.",
    "speakingTrackFocusTitle": "Lasoco diiradda",
    "speakingInterviewTitle": "Wareysi",
    "speakingGeneralWorkplaceScenariosTitle": "Xaaladaha goobta shaqada",
    "speakingProfessionWorkplaceScenariosTitle": "{profession} xaaladaha goobta shaqada",
    "speakingContextPracticeSuffix": "ku celceli xaaladaha gaagaaban ee goobta shaqada ee si toos ah luqadda ugu xidha hawlaha dhabta ah ee Finland.",
    "speakingDefaultPracticeSubtitle": "U adeegso hab-dhaqanka duruufaha tilmaamaha kormeeraha, xil-wareejinta, warbixinta arrinta, iyo xidhiidhka shaqada maalinlaha ah.",
    "speakingGeneralSupervisorTitle": "Tilmaamaha kormeeraha",
    "speakingGeneralSupervisorSummary": "Hubi faahfaahinta hawsha oo si cad ugu celi tilmaamaha muhiimka ah.",
    "speakingGeneralShiftHandoverTitle": "Xil wareejin",
    "speakingGeneralShiftHandoverSummary": "Sii warbixin kooban oo faa'iido leh oo ka caawisa qofka xiga inuu si habsami leh u bilaabo.",
    "speakingGeneralIssueReportingTitle": "Arrin ka warbixinta",
    "speakingGeneralIssueReportingSummary": "Sharax dhibaato, waxa aad samaysay, iyo gargaarka aad u baahan tahay marka xigta.",
    "speakingNurseShiftHandoverTitle": "Xil wareejin",
    "speakingNurseShiftHandoverSummary": "Si cad u soo koob isbeddellada, mudnaanta, iyo faahfaahinta badbaadada.",
    "speakingNursePatientUpdateTitle": "Cusboonaysiinta bukaanka",
    "speakingNursePatientUpdateSummary": "Ku qeex indho-indhaynta, raaxada, iyo ficilka xiga ee deggan Finnish.",
    "speakingNurseInterviewBetaTitle": "Beta waraysiga",
    "speakingNurseInterviewBetaSummary": "Kalkaaliye qaabaysan ku celcelinta waraysiga oo leh dardargelin xirfadeed oo gaar ah.",
    "speakingDoctorPatientInterviewTitle": "Wareysi bukaan",
    "speakingDoctorPatientInterviewSummary": "Weydii su'aalo kooban oo hubi fahamka ka hor intaadan u dhaqaaqin.",
    "speakingDoctorExplainNextStepsTitle": "Sharax talaabooyinka xiga",
